using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using System.Text.RegularExpressions;
using WhatsBiz.Application.Common.Exceptions;
using WhatsBiz.Application.Features.Storefront;

namespace WhatsBiz.Infrastructure.Storefront;

public sealed class StorefrontCustomerBlacklistService(IConfiguration configuration) : IStorefrontCustomerBlacklistService
{
    private string ConnectionString => configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Database connection unavailable.");
    public async Task<bool> IsBlockedAsync(Guid tenantId, string phone, CancellationToken token)
    { var normalized=Normalize(phone); if(normalized is null)return false; await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var q=new SqlCommand("SELECT COUNT(1) FROM commerce.StorefrontCustomerPhoneBlacklist WHERE TenantId=@tenant AND NormalizedPhone=@phone AND IsActive=1",c);Add(q,"@tenant",tenantId);Add(q,"@phone",normalized);return (int)(await q.ExecuteScalarAsync(token)??0)>0; }
    public async Task<StorefrontBlacklistPageDto> SearchAsync(Guid tenantId,bool activeOnly,string? search,int pageNumber,int pageSize,CancellationToken token)
    { pageNumber=Math.Clamp(pageNumber,1,1_000_000);pageSize=Math.Clamp(pageSize,1,100);var term=Normalize(search)??(string.IsNullOrWhiteSpace(search)?null:search.Trim());await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);var filter="TenantId=@tenant AND (@active=0 OR IsActive=1) AND (@search IS NULL OR NormalizedPhone LIKE N'%'+@search+N'%')";await using var count=new SqlCommand($"SELECT COUNT(1) FROM commerce.StorefrontCustomerPhoneBlacklist WHERE {filter}",c);Add(count,"@tenant",tenantId);Add(count,"@active",activeOnly);Add(count,"@search",term);var total=(int)(await count.ExecuteScalarAsync(token)??0);await using var q=new SqlCommand($"SELECT BlacklistId,NormalizedPhone,Reason,IsActive,BlockedBy,BlockedAtUtc,UnblockedBy,UnblockedAtUtc FROM commerce.StorefrontCustomerPhoneBlacklist WHERE {filter} ORDER BY BlockedAtUtc DESC OFFSET @skip ROWS FETCH NEXT @take ROWS ONLY",c);Add(q,"@tenant",tenantId);Add(q,"@active",activeOnly);Add(q,"@search",term);Add(q,"@skip",(pageNumber-1)*pageSize);Add(q,"@take",pageSize);var rows=new List<StorefrontBlacklistDto>();await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))rows.Add(Read(r));return new(rows,total,pageNumber,pageSize); }
    public async Task<StorefrontBlacklistDto> BlockAsync(Guid tenantId,Guid actorUserId,StorefrontBlacklistInput input,CancellationToken token)
    {var phone=Normalize(input.Phone)??throw new BusinessRuleException("Enter a valid phone number.");var reason=input.Reason?.Trim();if(string.IsNullOrWhiteSpace(reason)||reason.Length>500)throw new BusinessRuleException("A blacklist reason is required.");await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var existing=new SqlCommand("SELECT TOP(1)BlacklistId FROM commerce.StorefrontCustomerPhoneBlacklist WHERE TenantId=@tenant AND NormalizedPhone=@phone AND IsActive=1",c);Add(existing,"@tenant",tenantId);Add(existing,"@phone",phone);if(await existing.ExecuteScalarAsync(token) is Guid)throw new BusinessRuleException("This phone number is already blocked.");var id=Guid.NewGuid();await using var q=new SqlCommand("INSERT commerce.StorefrontCustomerPhoneBlacklist(BlacklistId,TenantId,NormalizedPhone,Reason,BlockedBy) VALUES(@id,@tenant,@phone,@reason,@actor)",c);Add(q,"@id",id);Add(q,"@tenant",tenantId);Add(q,"@phone",phone);Add(q,"@reason",reason);Add(q,"@actor",actorUserId);try{await q.ExecuteNonQueryAsync(token);}catch(SqlException ex)when(ex.Number is 2601 or 2627){throw new BusinessRuleException("This phone number is already blocked.");}return new(id,phone,reason,true,actorUserId.ToString(),DateTimeOffset.UtcNow,null,null);}
    public async Task<bool> UnblockAsync(Guid tenantId,Guid actorUserId,Guid blacklistId,CancellationToken token){await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var q=new SqlCommand("UPDATE commerce.StorefrontCustomerPhoneBlacklist SET IsActive=0,UnblockedBy=@actor,UnblockedAtUtc=SYSUTCDATETIME() WHERE TenantId=@tenant AND BlacklistId=@id AND IsActive=1",c);Add(q,"@tenant",tenantId);Add(q,"@id",blacklistId);Add(q,"@actor",actorUserId);return await q.ExecuteNonQueryAsync(token)==1;}
    private static StorefrontBlacklistDto Read(SqlDataReader r)=>new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetBoolean(3),r.IsDBNull(4)?null:r.GetGuid(4).ToString(),r.GetDateTimeOffset(5),r.IsDBNull(6)?null:r.GetGuid(6).ToString(),r.IsDBNull(7)?null:r.GetDateTimeOffset(7));
    private static string? Normalize(string? value){var x=Regex.Replace(value??"","[^0-9]","");return x.Length is >=10 and <=15?x:null;}
    private static void Add(SqlCommand c,string n,object? v)=>c.Parameters.AddWithValue(n,v??DBNull.Value);
}
